{"code": "import openpyxl
wb = openpyxl.load_workbook('materials/FinancialStatementFY26Q4.xlsx', data_only=False)
ws = wb['Segment Results']
print("=== Segment Results ===")
for r in range(1, ws.max_row+1):
    row = []
    for c in range(1, ws.max_column+1):
        row.append(ws.cell(row=r, column=c).value)
    print(r, row)
